const items = $input.all();
const allJobs = [];
const seenIds = new Set();

for (const item of items) {
  const htmlContent = item.json.data || item.json.body || item.json;
  if (typeof htmlContent !== 'string') continue;

  const cardRegex = /data-entity-urn="urn:li:jobPosting:(\d+)"[\s\S]*?<h3 class="base-search-card__title">\s*([\s\S]*?)\s*<\/h3>[\s\S]*?<h4 class="base-search-card__subtitle">\s*<a[^>]*>\s*([\s\S]*?)\s*<\/a>[\s\S]*?<span class="job-search-card__location">\s*([\s\S]*?)\s*<\/span>/g;

  let match;
  while ((match = cardRegex.exec(htmlContent)) !== null) {
    const jobId = match[1];
    let title = match[2].replace(/<[^>]+>/g, '').trim();
    let company = match[3].replace(/<[^>]+>/g, '').trim();
    let location = match[4].replace(/<[^>]+>/g, '').trim();

    if (location.toLowerCase().includes('singapore') && !seenIds.has(jobId)) {
      seenIds.add(jobId);
      allJobs.push({
        jobId,
        title,
        company,
        location,
        jobUrl: `https://sg.linkedin.com/jobs/view/${jobId}`,
        query: item.json.query || 'Middleware'
      });
    }
  }
}

return allJobs.map(j => ({ json: j }));

const job = $('Batch Loop Over Jobs').item.json;
const htmlDetail = $input.first().json.data || $input.first().json.body || '';

const cleanDesc = (typeof htmlDetail === 'string' ? htmlDetail : '')
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 3500);

const resumeProfile = `
Name: Meliton Mark P. Salva III
Title: Systems Analyst / Software Engineer / Middleware Developer
Experience: 19+ years in Systems Analysis, Middleware Integration, Banking/Enterprise Systems (MUFG Bank, HDB).
Core Skills:
- Integration Platforms: IBM App Connect Enterprise (ACE) Toolkit, IBM Integration Bus (IIB) Toolkit, IBM WebSphere MQ, Message Broker
- Programming & Scripting: ESQL, Shell Scripting, Lotus Formula, Lotus Script, VB Scripting, VB.Net, Java, XML, JavaScript, JQuery
- Databases: Oracle, DB2, SQL Server
- Messaging & Queuing: IBM MQ
- Stakeholder Management, Systems Analysis, SIT/UAT/PROD support.
`;

const aiPrompt = `
You are an expert IT/Banking Technical Recruiter. Evaluate if the following job posting in Singapore fits the candidate profile.

[CANDIDATE PROFILE]
${resumeProfile}

[JOB POSTING]
Title: ${job.title}
Company: ${job.company}
Location: ${job.location}
Description:
${cleanDesc}

[EVALUATION RULES]
1. Return ONLY valid raw JSON with keys: "isMatch" (boolean), "matchScore" (integer 0-100), "matchRationale" (string, 1-2 concise sentences summarizing skill match), "keyMatchedSkills" (array of strings).
2. Set isMatch=true if matchScore >= 60. High match for IBM ACE/IIB, WebSphere MQ, ESQL, Middleware, Systems Analysis, Banking IT, Java/SQL integration.
3. Set isMatch=false if unrelated field or zero skill overlap.
`;

return [{ json: { ...job, jobDescription: cleanDesc, aiPrompt } }];

const job = $('Prep AI Prompt').item.json;
const aiRaw = $input.first().json;

let evalRes = { isMatch: false, matchScore: 0, matchRationale: '', keyMatchedSkills: [] };
try {
  const content = aiRaw.choices[0].message.content.replace(/```json|```/g, '').trim();
  evalRes = JSON.parse(content);
} catch(e) {
  evalRes = { isMatch: false, matchScore: 0, matchRationale: 'Parsing error', keyMatchedSkills: [] };
}

const titleLinked = `=HYPERLINK("${job.jobUrl}", "${job.title.replace(/"/g, '""')}")`;
const todayStr = new Date().toISOString().split('T')[0];

return [{
  json: {
    ...job,
    isMatch: evalRes.isMatch || evalRes.matchScore >= 60,
    matchScore: evalRes.matchScore || 0,
    matchRationale: evalRes.matchRationale || '',
    matchedSkills: (evalRes.keyMatchedSkills || []).join(', '),
    titleLinked,
    dateFound: todayStr
  }
}];
